    // --- Guide: install-location cards ---
    guideInstallPluginsTitle: "פלאגינים",
    guideInstallPluginsBody: "קובצי .jar בתיקיית plugins של השרת. רק על ליבות תומכות-פלאגינים (Paper/Purpur/Folia/Mohist/Youer). ProtocolLib וספריות הן גם .jar כאן — לא datapack.",
    guideInstallDataTitle: "דאטה-פאקים",
    guideInstallDataBody: "נכנסים לתיקיית world/datapacks. עובדים על כל שרת — כולל ונילה. Worldgen (Terralith/Tectonic) דורש עולם חדש ולא עובד על Paper/Purpur/Folia.",
    guideInstallModsTitle: "מודים",
    guideInstallModsBody: "קובצי .jar בתיקיית mods. רק על Forge/NeoForge/Fabric/Quilt. שינוי עמוק — בלוקים/חיות/ממדים. כל שחקן צריך את אותם מודים בדיוק.",
    guideInstallPcTitle: "שיידרים, טקסטורות ומודי צד-שחקן",
    guideInstallPcBody: "Shaders, מודי צד-שחקן (Sodium, מיני-מפה) ו-Resource Packs יושבים על מחשב השחקן. השרת לא יודע מהם. Resource Pack אפשר גם לדחוף מהשרת (server-resource-pack).",
    // --- Guide: compatibility rules — title / body per rule ---
    guideCompatCoreLockTitle: "אי אפשר לערבב מודים ופלאגינים",
    guideCompatCoreLockBody: "שרת פלאגינים לא מריץ מודים, ושרת מודים לא מריץ פלאגינים. רוצים את שניהם יחד? צריך שרת היברידי (<bdi>Mohist</bdi>/<bdi>Youer</bdi>) — פחות יציב.",
    guideCompatProtocolLibTitle: "פלאגינים שצריכים עוזר",
    guideCompatProtocolLibBody: "כמה פלאגינים לא עובדים לבד — הם צריכים את הפלאגין <bdi>ProtocolLib</bdi> מותקן לצידם. בלעדיו הם לא יעלו.",
    guideCompatEssentialsTitle: "התאמת גרסה לפלאגין",
    guideCompatEssentialsBody: "פלאגין כמו <bdi>EssentialsX</bdi> צריך גרסה שמתאימה לגרסת <bdi>Paper</bdi> שלך. גרסה ישנה מדי על שרת חדש — עלולה לא לעבוד.",
    guideCompatWorldgenTitle: "Worldgen datapacks",
    guideCompatWorldgenBody: "Terralith / Tectonic רצים רק על Vanilla / Fabric / Forge / NeoForge (לא Paper / Purpur / Folia) — ודורשים עולם חדש.",
    guideCompatDepsTitle: "תלויות (Dependencies)",
    guideCompatDepsBody: "Slimefun → Vault · ItemsAdder → ProtocolLib · MythicMounts → MythicMobs · ExcellentEnchants → NightCore. במאגר שלנו התלויות מסומנות ומותקנות אוטומטית.",
    guideCompatServerModsTitle: "Server-side mods",
    guideCompatServerModsBody: "מודים שיושבים רק בשרת (FTB Chunks, Essential Commands) ומחליפים פלאגינים — השחקן נכנס נקי, בלי להתקין כלום.",
    guideCompatItemsAdderTitle: "ItemsAdder / Slimefun / Oraxen",
    guideCompatItemsAdderBody: "אלה פלאגינים (לא טקסטורות!) שמוסיפים פריטים דרך Custom-Model-Data + resource-pack אוטומטי. ItemsAdder = פרימיום בתשלום + דורש ProtocolLib.",
    guideCompatRpAloneTitle: "Resource Pack לבד",
    guideCompatRpAloneBody: "לא מוסיף פריטים — רק משנה מראה של פריטים קיימים. פריט חדש דורש פלאגין (ItemsAdder) או datapack.",
    guideCompatSinytraTitle: "Sinytra Connector",
    guideCompatSinytraBody: "מוד Forge שמריץ מודי Fabric / Quilt (גשר — לא מושלם).",
    guideCompatFoliaTitle: "Folia",
    guideCompatFoliaBody: "הרבה פלאגינים רגילים קורסים עליו — לא מותאמים למרובה-ליבות.",
    guideCompatViaVersionTitle: "ViaVersion",
    guideCompatViaVersionBody: "פלאגין שמאפשר לשחקנים מגרסאות מיינקראפט שונות להיכנס לאותו שרת. עובד רק על Paper / Purpur — לא על מודים (שם כולם חייבים אותה גרסה בדיוק).",
    guideCompatVoiceChatTitle: "Simple Voice Chat",
    guideCompatVoiceChatBody: "מוד צ'אט-קולי שדורש פתיחת פורט UDP בשרת.",
