    guideRamNote: "הכלל פשוט: יותר מודים = יותר RAM. ונילה ו-Paper רצים רזה; מודפאק כבד יכול להגיע ל-8GB ומעלה — גם עם מעט שחקנים. בורר ה-RAM של OmriCraft מאפשר להקצות עד 12GB לשרת.",
