    guideAltCosmeticMod: "(מודים מוסיפים ישירות)",
    // --- Guide: resource-pack explainer (plain-text paragraphs) ---
    guideRpP1: "Resource Pack (חבילת-משאבים / טקסטורות) משנה רק את המראה — בלוקים, צלילים ומודלים של פריטים קיימים. הוא לא מוסיף פריטים חדשים בעצמו.",
    guideRpP2: "אפשר לטעון אותו בשתי דרכים: (1) הורדה למחשב של השחקן — אותו קובץ .zip עובד בכל שרת ובסינגל-פלייר; או (2) דחיפה אוטומטית מהשרת (server-resource-pack) — כל שחקן שנכנס מתבקש לאשר ולהוריד אותו אוטומטית, בלי להתקין כלום.",
    guideRpP3: "כדי להוסיף פריט חדש לגמרי (להחזיק, לחבוש, לזרוק, למכור) צריך פלאגין-תשתית כמו ItemsAdder / Oraxen (Custom-Model-Data) או datapack — חבילת-טקסטורות לבדה לא מספיקה. ItemsAdder = פרימיום בתשלום ודורש ProtocolLib, רץ רק על Paper / Purpur.",
    // --- Guide: modpack explainer (plain-text paragraphs) ---
    guideMpP1: "שרת מודפאק הוא מולטי-פלייר מלא — מארח הרבה שחקנים, לא רק שחקן יחיד. הבלבול נובע מכך שרוב המשחק במודפאק נעשה בסינגל-פלייר.",
    guideMpP2: "כל שחקן חייב להריץ את אותו מודפאק בדיוק במחשבו — מותקן בלחיצה דרך CurseForge או Modrinth. אין תרגום-גרסאות (ViaVersion לא חל על מודים): כולם חייבים אותו loader, אותה גרסת מיינקראפט ואותם קובצי-מודים.",
    guideMpP3: "מודפאקים כבדים זללני-זיכרון — ראו טבלת ה-RAM למעלה. גם 2 שחקנים על מודפאק כבד צריכים 8GB ומעלה.",
    // --- Guide: slide-deck reorg (two tracks · handshake · 3-column install) ---
    guideFamPluginsTagline: "חיבור נקי (Server-Side Only) — השחקן לא מתקין כלום.",
    guideFamModsTagline: "שינוי עמוק (Client-Server Sync) — השחקן חייב התאמה במחשב שלו.",
    guideFamHybridWarn: "גשר בין שני העולמות — לא מסלול שלישי שווה-ערך, אלא פתרון-קצה עם סיכון תאימות.",
    guideGroupModsTitle: "מנועי מודים",
    guideSyncTitle: "שרתי מודים · חובה שהכול תואם",
    guideSync1Title: "אותה גרסה",
    guideSync1Body: "לשרת ולשחקן צריכה להיות בדיוק אותה גרסת מיינקראפט. גרסה שונה — לא מתחברים.",
    guideSync2Title: "אותה תוכנת-שרת",
    guideSync2Body: "אם השרת על <bdi>Fabric</bdi> — כל שחקן צריך <bdi>Fabric</bdi>. אם על <bdi>Forge</bdi> — כולם על <bdi>Forge</bdi>. אי אפשר לערבב.",
    guideSync3Title: "אותם מודים",
    guideSync3Body: "כל מוד שיש בשרת צריך להיות גם אצל כל שחקן, באותה גרסה. חסר מוד אצל שחקן — הוא לא ייכנס.",
    guideSyncEasyWay: "הדרך הקלה: מתקינים modpack דרך Modrinth / CurseForge — שלושת התנאים מסתנכרנים אוטומטית בלחיצה אחת.",
    guideSyncMoreRules: "עוד כללים חשובים",
    guideInstallColServer: "השרת",
    guideInstallColServerSub: "מותקן רק בשרת — השחקן לא מתקין כלום",
    guideInstallColBoth: "חובה בשני הצדדים",
    guideInstallColBothSub: "אותם קבצים בשרת וגם אצל כל שחקן",
    guideInstallColPc: "מחשב השחקן (צד-שחקן)",
    guideInstallColPcSub: "מה שכל שחקן מתקין אצלו",
