    guideInstallExcServer: "יוצא-דופן: דאטה-פאק שבונה עולם חדש צריך עולם חדש לגמרי, והוא לא רץ על <bdi>Paper</bdi>/<bdi>Purpur</bdi>/<bdi>Folia</bdi>.",
    guideInstallExcBoth: "יוצא-דופן: במודים צריך אותה גרסה ואת אותם מודים בשני הצדדים — גם בשרת וגם אצל כל שחקן.",
    guideInstallServerRpTitle: "טקסטורות מהשרת",
    guideInstallServerRp: "השרת יכול לשלוח טקסטורות אוטומטית לכל מי שמתחבר — כך כולם רואים את אותו מראה בלי להתקין ידנית.",
    guideAltIntro: "מטריצת הגירה: עוברים בין ליבת פלאגינים לליבת מודים? לכל תפקיד יש מקבילה בצד השני.",
    guideRpP4: "הטריק הגדול — «להיראות כמו מודים בלי מודים»: פלאגינים כמו ItemsAdder / Oraxen משלבים Custom-Model-Data עם resource-pack שנדחף מהשרת, ויוצרים פריטים ומובים מותאמים-אישית על שרת פלאגינים רגיל — והשחקן לא מתקין כלום.",

