    guideEnvVanillaLine: "Mojang's original Minecraft, with nothing extra on the server. On the server you install only data packs; textures, shaders and player-side mods go on the player's computer.",
    guideEnvPluginsLine: "From the Bukkit/Spigot family. You add powers to the server — mini-games, protections and commands — without the player installing anything. On the server you install plugins and data packs.",
    guideEnvModsLine: "They change the game itself — blocks, creatures, dimensions. You need the server software in the right version, and every player installs the same mods on their own computer. On the server you install mods and data packs.",
    guideEnvHybridLine: "Runs mods and plugins together, but less stable — a bridge, not a first choice. On the server you install a plugin, a mod and a data pack.",
    guideEnvFlipHint: "Hover to see the server types →",
