    guidePickTopic: "Pick a topic",
    guideAddonModsName: "Mods",
    guidePluginNote: "The \"plugin format\" = Bukkit/Spigot API. Paper is a fork of Spigot.",
    // --- Guide: server-core family cards (א) ---
    guideFamPluginsBody: "Don't touch the game files — add commands, economy, protections and permissions on the server side. Players join with the normal game, installing nothing. The \"plugin format\" = Bukkit/Spigot API; Paper is a fork of Spigot.",
    guideFamModsBody: "Change the game deeply — new blocks, mobs and dimensions. Require every player to install the exact same loader and the exact same mods on their PC. Heavier on memory.",
    guideFamHybridBody: "Run Forge/NeoForge mods and Bukkit plugins together — only when you truly need the combination. Mohist is EOL and unstable; Youer is the maintained successor (NeoForge) and is recommended.",
    // --- Guide: server-core comparison table (ב) — what / who per core ---
    guideCoreVanillaWhat: "Original Minecraft, no extra code",
    guideCoreVanillaWho: "Regular play (Data Packs only)",
    guideCorePaperWhat: "The popular core — fast with tons of plugins",
    guideCorePaperWho: "Survival / mini-games",
    guideCorePurpurWhat: "Paper with lots more settings to tweak",
    guideCorePurpurWho: "Extreme customization",
    guideCoreFoliaWhat: "Core for huge servers with many players",
