    guideCoreForgeWhat: "The veteran core for big mods",
    guideCoreForgeWho: "RLCraft / SkyFactory (RAM hog)",
    guideCoreNeoForgeWhat: "A modern, updated version of Forge",
    guideCoreNeoForgeWho: "The new standard for mods",
    guideCoreFabricWhat: "Light, fast core for running mods",
    guideCoreFabricWho: "Light mods / optimization",
    guideCoreQuiltWhat: "Like Fabric with a few extra features",
    guideCoreQuiltWho: "Compatible with most Fabric mods",
    guideCoreMohistWhat: "Runs both mods and plugins together",
    guideCoreMohistWho: "Only when you must combine — unstable, EOL",
