    guideFamPluginsBody: "On ne touche pas aux fichiers du jeu — on ajoute des commandes, une économie, des protections et des permissions côté serveur. Les joueurs se connectent avec un client vanilla normal, sans rien installer. Le « format plugin » = l'API Bukkit/Spigot ; Paper est un fork de Spigot.",
    guideFamModsBody: "Ils modifient le jeu en profondeur — nouveaux blocs, mobs et dimensions. Ils exigent que chaque joueur installe exactement le même loader et exactement les mêmes mods sur son PC. Plus gourmands en mémoire.",
    guideFamHybridBody: "Faire tourner des mods Forge/NeoForge et des plugins Bukkit ensemble — uniquement quand vous avez vraiment besoin de cette combinaison. Mohist est EOL et instable ; Youer est le successeur maintenu (NeoForge) et il est recommandé.",
    guideCoreVanillaWhat: "Minecraft original, sans code ajouté",
    guideCoreVanillaWho: "Jeu classique (Data Packs uniquement)",
    guideCorePaperWhat: "Le core populaire — rapide avec plein de plugins",
    guideCorePaperWho: "Survie / mini-jeux",
    guideCorePurpurWhat: "Paper avec beaucoup plus de réglages",
    guideCorePurpurWho: "Personnalisation extrême",
    guideCoreFoliaWhat: "Core pour serveurs géants avec beaucoup de joueurs",
    guideCoreFoliaWho: "Serveurs géants 100+ (beaucoup de plugins y plantent)",
    guideCoreForgeWhat: "Le core vétéran pour les gros mods",
    guideCoreForgeWho: "RLCraft / SkyFactory (dévoreur de RAM)",
    guideCoreNeoForgeWhat: "Une version moderne et à jour de Forge",
    guideCoreNeoForgeWho: "Le nouveau standard pour les mods",
    guideCoreFabricWhat: "Core léger et rapide pour les mods",
    guideCoreFabricWho: "Mods légers / optimisation",
