    guideCoreQuiltWho: "Compatible avec la plupart des mods Fabric",
    guideCoreMohistWhat: "Fait tourner mods et plugins ensemble",
    guideCoreMohistWho: "Uniquement quand la combinaison est indispensable — instable, EOL",
    guideCoreYouerWhat: "Nouvel hybride pour mods et plugins ensemble",
    guideCoreYouerWho: "Mods + plugins ensemble (recommandé plutôt que Mohist)",
