    guidePlayerSideNote: "* Côté joueur = l'ordinateur de la personne qui joue (client)",
    guideInstallExcServer: "Exception : un data pack de génération de monde (worldgen) demande un monde tout neuf, et ne fonctionne pas sur <bdi>Paper</bdi>/<bdi>Purpur</bdi>/<bdi>Folia</bdi>.",
    guideInstallExcBoth: "Exception : avec les mods il faut la même version et les mêmes mods des deux côtés — sur le serveur et chez chaque joueur.",
    guideInstallServerRpTitle: "Pack de ressources du serveur",
    guideInstallServerRp: "Le serveur peut envoyer les textures automatiquement à tous ceux qui se connectent — ainsi tout le monde voit le même rendu sans rien installer à la main.",
    guideAltIntro: "La matrice de migration : vous passez d'un cœur plugins à un cœur mods ? Chaque rôle a son équivalent de l'autre côté.",
    guideRpP4: "Le grand truc — « ressembler à des mods sans mods » : des plugins comme ItemsAdder / Oraxen combinent Custom-Model-Data et resource-pack poussé par le serveur pour créer objets et mobs personnalisés sur un serveur plugins classique — le joueur n'installe rien.",
