    guideEnvVanillaLine: "Le Minecraft original de Mojang, sans rien de plus sur le serveur. Sur le serveur on installe seulement des data packs ; textures, shaders et mods côté joueur vont sur l'ordinateur du joueur.",
    guideEnvPluginsLine: "De la famille Bukkit/Spigot. On ajoute des capacités au serveur — mini-jeux, protections et commandes — sans que le joueur installe quoi que ce soit. Sur le serveur on installe des plugins et des data packs.",
