    guideInstallColPcSub: "Ciò che ogni giocatore installa sul proprio dispositivo",
    guidePlayerSideNote: "* Lato giocatore = il computer di chi gioca (client)",
    guideInstallExcServer: "Eccezione: un data pack di generazione mondo (worldgen) richiede un mondo nuovo e non funziona su <bdi>Paper</bdi>/<bdi>Purpur</bdi>/<bdi>Folia</bdi>.",
    guideInstallExcBoth: "Eccezione: con i mod servono la stessa versione e gli stessi mod su entrambi i lati — sul server e su ogni giocatore.",
    guideInstallServerRpTitle: "Pacchetto risorse dal server",
    guideInstallServerRp: "Il server può inviare le texture automaticamente a chiunque si colleghi — così tutti vedono lo stesso aspetto senza installare nulla a mano.",
    guideAltIntro: "La matrice di migrazione: passi da un core plugin a un core mod? Ogni ruolo ha il suo equivalente dall'altra parte.",
    guideRpP4: "Il grande trucco — «sembrare mod senza mod»: plugin come ItemsAdder / Oraxen combinano Custom-Model-Data con un resource-pack inviato dal server per creare oggetti e mob personalizzati su un normale server plugin — e il giocatore non installa nulla.",
