    guideEnvVanillaLine: "Il Minecraft originale di Mojang, senza aggiunte sul server. Sul server installi solo i data pack; texture, shader e mod lato giocatore vanno sul computer del giocatore.",
    guideEnvPluginsLine: "Dalla famiglia Bukkit/Spigot. Aggiungi capacità al server — mini-giochi, protezioni e comandi — senza che il giocatore installi nulla. Sul server installi plugin e data pack.",
