    guideFamPluginsBody: "Não mexem nos arquivos do jogo — adicionam comandos, economia, proteções e permissões no lado do servidor. O jogador entra com um cliente vanilla normal, sem instalar nada. O \"formato de plugin\" = Bukkit/Spigot API; o Paper é um fork do Spigot.",
    guideFamModsBody: "Alteram o jogo profundamente — novos blocos, mobs e dimensões. Exigem que todo jogador instale exatamente o mesmo loader e exatamente os mesmos mods no PC. Mais pesados na memória.",
    guideFamHybridBody: "Rodam mods de Forge/NeoForge e plugins de Bukkit juntos — só quando você realmente precisa da combinação. O Mohist é EOL e instável; o Youer é o sucessor mantido (NeoForge) e é o recomendado.",
    guideCoreVanillaWhat: "O servidor oficial da Mojang, limpo",
    guideCoreVanillaWho: "Jogo comum (apenas Data Packs)",
    guideCorePaperWhat: "O padrão da indústria — build otimizada, \"o rei dos plugins\"",
    guideCorePaperWho: "Survival / mini-games",
    guideCorePurpurWhat: "Um fork do Paper, centenas de configurações",
    guideCorePurpurWho: "Personalização extrema",
    guideCoreFoliaWhat: "Paper multi-core (multi-thread)",
    guideCoreFoliaWho: "Servidores gigantes 100+ (muitos plugins travam nele)",
    guideCoreForgeWhat: "O antigo e pesado — modpacks gigantes",
    guideCoreForgeWho: "RLCraft / SkyFactory (devora RAM)",
    guideCoreNeoForgeWhat: "Um fork moderno do Forge (1.20+)",
    guideCoreNeoForgeWho: "O novo padrão para mods",
    guideCoreFabricWhat: "Leve e rápido, atualiza na hora",
    guideCoreFabricWho: "Mods leves / otimização",
    guideCoreQuiltWhat: "Um fork comunitário do Fabric",
    guideCoreQuiltWho: "Compatível com a maioria dos mods de Fabric",
    guideCoreMohistWhat: "Mods de Forge + plugins juntos",
    guideCoreMohistWho: "Só quando você precisa combinar — instável, EOL",
    guideCoreYouerWhat: "Híbrido NeoForge — o sucessor mantido do Mohist",
    guideCoreYouerWho: "Mods + plugins juntos (recomendado em vez do Mohist)",
    guideMaybeTitle: "Parcial / instável",
    guideAddonModsDoes: "Novos blocos / mobs / dimensões (alteração profunda)",
    guideAddonModsWhere: "Servidor + PC",
    guideAddonModsServers: "Forge / NeoForge / Fabric / Quilt",
    guideAddonModsName: "Mods",
    guideBackToAll: "Voltar ao guia",
