    guideAddonPluginsDoes: "Comandos, economia, proteções, permissões (sem novos blocos)",
    guideAddonPluginsWhere: "Apenas no servidor",
    guideAddonPluginsServers: "Paper / Purpur / Folia / Mohist / Youer",
    guideAddonDataDoes: "Receitas / estruturas / quests (vanilla oficial)",
    guideAddonDataWhere: "Servidor — world/datapacks",
    guideAddonDataServers: "Qualquer servidor (incluindo vanilla)",
    guideAddonModpackDoes: "Um pacote inteiro de mods — servidor + cada jogador",
    guideAddonModpackWhere: "Servidor + PC de cada jogador",
    guideAddonModpackServers: "Forge / NeoForge / Fabric",
    guideAddonRpDoes: "Aparência: blocos, sons, modelos",
