,
    guideFamPluginsBody: "لا تلمس ملفات اللعبة — أضِف الأوامر والاقتصاد والحمايات والصلاحيات من جهة الخادم. ينضم اللاعبون بعميل vanilla عادي دون تثبيت أي شيء. «صيغة الـ plugin» = Bukkit/Spigot API؛ وPaper هو fork من Spigot.",
    guideFamModsBody: "تغيّر اللعبة بعمق — بلوكات ومخلوقات وأبعاد جديدة. تتطلب من كل لاعب تثبيت نفس الـ loader ونفس الـ mods بالضبط على حاسوبه. أثقل على الذاكرة.",
    guideFamHybridBody: "تشغّل mods الخاصة بـ Forge/NeoForge وplugins الخاصة بـ Bukkit معًا — فقط عندما تحتاج فعلًا إلى هذا الدمج. Mohist وصل إلى EOL وغير مستقر؛ وYouer هو الخليفة المُصان (NeoForge) وهو المُوصى به.",
    guideCoreVanillaWhat: "خادم Mojang الرسمي، نظيف",
    guideCoreVanillaWho: "لعب عادي (Data Packs فقط)",
