    guideAddonClientServers: "الخادم لا يعلم عنه شيئًا",
    guideInstallPluginsTitle: "Plugins",
    guideInstallPluginsBody: "ملفات .jar في مجلد plugins الخاص بالخادم. فقط على النوى الداعمة للـ plugins (Paper/Purpur/Folia/Mohist/Youer). ProtocolLib والمكتبات هي أيضًا ملفات .jar هنا — وليست datapack.",
    guideInstallDataTitle: "Data Packs",
    guideInstallDataBody: "توضع في مجلد world/datapacks. تعمل على أي خادم — بما في ذلك vanilla. توليد العالم (Terralith/Tectonic) يحتاج إلى عالم جديد ولا يعمل على Paper/Purpur/Folia.",
    guideInstallModsTitle: "Mods",
    guideInstallModsBody: "ملفات .jar في مجلد mods. فقط على Forge/NeoForge/Fabric/Quilt. تغيير عميق — بلوكات/مخلوقات/أبعاد. كل لاعب يحتاج إلى نفس الـ mods بالضبط.",
    guideInstallPcTitle: "حاسوب اللاعب",
    guideInstallPcBody: "الـ shaders، وmods جهة العميل (Sodium، الخريطة المصغّرة) والـ Resource Packs تعيش على حاسوب اللاعب. الخادم لا يعلم عنها شيئًا. يمكن أيضًا دفع الـ Resource Pack من الخادم (server-resource-pack).",
    guideCompatCoreLockTitle: "قفل النواة",
    guideCompatCoreLockBody: "بعض الإضافات تعمل على نواة واحدة فقط: Sodium / C2ME = Fabric فقط · Create = Forge / NeoForge فقط.",
    guideCompatWorldgenTitle: "Worldgen datapacks",
    guideCompatWorldgenBody: "Terralith / Tectonic تعمل فقط على Vanilla / Fabric / Forge / NeoForge (وليس Paper / Purpur / Folia) — وتتطلب عالمًا جديدًا.",
    guideCompatDepsTitle: "التبعيات (Dependencies)",
    guideCompatDepsBody: "Slimefun → Vault · ItemsAdder → ProtocolLib · MythicMounts → MythicMobs · ExcellentEnchants → NightCore. في كتالوجنا يتم تمييز التبعيات وتثبيتها تلقائيًا.",
    guideCompatServerModsTitle: "Server-side mods",
    guideCompatServerModsBody: "mods تعيش على الخادم فقط (FTB Chunks، Essential Commands) وتحل محل الـ plugins — ينضم اللاعب نظيفًا دون تثبيت أي شيء.",
    guideCompatItemsAdderTitle: "ItemsAdder / Slimefun / Oraxen",
    guideCompatItemsAdderBody: "هذه plugins (وليست textures!) تضيف عناصر عبر Custom-Model-Data + resource-pack تلقائي. ItemsAdder = premium مدفوع + يتطلب ProtocolLib.",
    guideCompatRpAloneTitle: "Resource Pack بمفرده",
    guideCompatRpAloneBody: "لا يضيف عناصر — فقط يعيد كساء العناصر الموجودة. العنصر الجديد يتطلب plugin (ItemsAdder) أو datapack.",
    guideCompatSinytraTitle: "Sinytra Connector",
    guideCompatSinytraBody: "mod خاص بـ Forge يشغّل mods الخاصة بـ Fabric / Quilt (جسر — وليس مثاليًا).",
    guideCompatFoliaTitle: "Folia",
    guideCompatFoliaBody: "كثير من الـ plugins العادية تنهار عليه — فهي ليست مهيّأة للنوى المتعددة.",
    guideCompatViaVersionTitle: "ViaVersion",
    guideCompatViaVersionBody: "plugin يترجم بروتوكولات الشبكة → ينضم لاعبون من إصدارات مختلفة إلى نفس الخادم. يعمل فقط على Paper / Purpur (vanilla). لا يعمل مع الـ mods — فهناك يجب أن يمتلك اللاعب نفس النواة+الإصدار+الـ mods بالضبط. الاستثناء: خادم يشغّل server-side mods فقط (أوامر، بدون بلوكات جديدة).",
    guideCompatVoiceChatTitle: "Simple Voice Chat",
    guideCompatVoiceChatBody: "mod للدردشة الصوتية يتطلب فتح منفذ UDP على الخادم.",
    guideRamHeadKind: "نوع الخادم",
    guideRamHeadRam: "الذاكرة المُوصى بها",
    guideRam1Kind: "Vanilla / Paper",
    guideRam1Ram: "2GB تكفي لـ~20 لاعبًا (حمل ضئيل)",
    guideRam2Kind: "modpack خفيف (≤50 mods)",
    guideRam2Ram: "4GB (1–5 لاعبين)",
    guideRam3Kind: "modpack متوسط (50–150)",
    guideRam3Ram: "4–6GB + 2GB لكل 5 لاعبين إضافيين",
    guideRam4Kind: "modpack ثقيل (150–300+، Better MC / Vault Hunters)",
    guideRam4Ram: "6–8GB كحد أدنى (حتى لاثنين!)، 12GB+ لعشرة",
    guideRamNote: "الـ mods = نهمة للـ RAM: كل لاعب يتطلب معالجة هائلة للآلات / الأحياء الحيوية. تعمل Vanilla وPaper بخفة (~1–2GB)؛ أما الـ modpacks الثقيلة (مثل Better MC) فتصل إلى 8GB وأكثر. يتيح محدد الـ RAM في OmriCraft تخصيص حتى 12GB لكل خادم.",
    guideAltHeadRole: "الدور",
    guideAltHeadPlugin: "Plugin (Paper)",
    guideAltHeadMod: "Mod (Forge / Fabric)",
    guideAlt1Role: "أوامر (Home/Spawn)",
    guideAlt2Role: "حماية الأراضي",
    guideAlt3Role: "خريطة ويب",
    guideAlt4Role: "تحرير العالم",
    guideAlt5Role: "مهارات RPG",
    guideAlt6Role: "عناصر تجميلية",
    guideAlt7Role: "تحسين الأداء",
    guideAlt8Role: "دردشة صوتية",
    guideAltCosmeticMod: "(الـ mods تضيفها مباشرة)",
    guideRpP1: "الـ Resource Pack (حزمة موارد / textures) يغيّر المظهر فقط — بلوكات وأصوات ونماذج العناصر الموجودة. وهو لا يضيف عناصر جديدة بمفرده.",
    guideRpP2: "يمكنك تحميله بطريقتين: (1) التنزيل إلى حاسوب اللاعب — نفس ملف .zip يعمل على أي خادم وفي وضع اللاعب الفردي؛ أو (2) الدفع التلقائي من الخادم (server-resource-pack) — كل لاعب ينضم يُطلب منه الموافقة وتنزيله تلقائيًا دون تثبيت أي شيء.",
    guideRpP3: "لإضافة عنصر جديد تمامًا (لحمله أو ارتدائه أو رميه أو بيعه) تحتاج إلى plugin داعم مثل ItemsAdder / Oraxen (Custom-Model-Data) أو datapack — لا تكفي حزمة textures بمفردها. ItemsAdder = premium مدفوع ويتطلب ProtocolLib، ويعمل فقط على Paper / Purpur.",
    guideMpP1: "خادم الـ modpack هو multiplayer كامل — يستضيف عددًا كبيرًا من اللاعبين، وليس لاعبًا واحدًا فقط. ينشأ اللبس من أن معظم اللعب في الـ modpack يتم في وضع اللاعب الفردي.",
    guideMpP2: "يجب أن يشغّل كل لاعب نفس الـ modpack بالضبط على حاسوبه — مُثبّت بنقرة واحدة عبر CurseForge أو Modrinth. لا يوجد ترجمة للإصدارات (ViaVersion لا ينطبق على الـ mods): يجب أن يمتلك الجميع نفس الـ loader، ونفس إصدار Minecraft، ونفس ملفات الـ mods.",
    guideMpP3: "الـ modpacks الثقيلة نهمة للذاكرة — راجع جدول الـ RAM أعلاه. حتى لاعبان على modpack ثقيل يحتاجان إلى 8GB وأكثر."
